"""Fusions of a (possibly non-commutative) homogeneous coherent configuration generated by one relation.

For every transposition-closed union S of non-trivial classes, the closure of the partition {0} | S | rest is
computed by refinement inside the algebra: blocks are split by the vector of block-product coefficients
sum_{i in X, j in Y} p^k_ij (over all pairs of blocks X, Y) and by the block of the transposed class, until
stable. The result is the coarsest fusion in which S is a union of classes (the coherent closure of the graph S,
which is a fusion because the configuration is coherent). Every rank-3 fusion arises this way, and so does every
fusion that is generated by one of its relations. Distinct fusions are collected and tested for commutativity
and symmetry; the lattice under refinement is written as well.

Usage: python fusion_closure.py <intersection_numbers.csv> <out.json> [shard nshard]
       python fusion_closure.py merge <intersection_numbers.csv> <out.json> <part.json> ...
"""
import os, sys, json, time
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from srg_drg_search import load_p, structure

P = None
PAIR = None
UNITS = None


def init(path):
    global P, PAIR, UNITS
    P = load_p(path)
    _, PAIR, UNITS = structure(P)
    PAIR = np.array(PAIR)


def refine(labels):
    """labels: int array of length r with labels[0] unique. Returns canonical labels of the closure."""
    r = P.shape[0]
    while True:
        b = int(labels.max()) + 1
        if b == r:
            return tuple(int(v) for v in labels)
        M = np.zeros((b, r), dtype=np.int64)
        M[labels, np.arange(r)] = 1
        T1 = np.tensordot(M, P, axes=(1, 0))          # (b, j, k) = sum_{i in X} p^k_ij
        C = np.tensordot(T1, M, axes=(1, 1))          # (b, k, b) = sum_{i in X, j in Y} p^k_ij
        sig = np.concatenate([labels[:, None], labels[PAIR][:, None], C.transpose(1, 0, 2).reshape(r, -1)], axis=1)
        _, first, inv = np.unique(sig, axis=0, return_index=True, return_inverse=True)
        order = np.argsort(first)
        relab = np.empty(len(order), dtype=np.int64)
        relab[order] = np.arange(len(order))
        new = relab[inv.ravel()]
        if new.max() == labels.max():
            return tuple(int(v) for v in new)
        labels = new


def closure_of(mask):
    r = P.shape[0]
    lab = np.full(r, 2, dtype=np.int64)
    lab[0] = 0
    for a, u in enumerate(UNITS):
        if mask >> a & 1:
            lab[u] = 1
    # canonical first-occurrence labels
    _, first = np.unique(lab, return_index=True)
    order = np.argsort(first); relab = np.empty(len(order), dtype=np.int64); relab[order] = np.arange(len(order))
    return refine(relab[lab])


def fused_constants(p, labels):
    b = max(labels) + 1
    r = p.shape[0]
    M = np.zeros((b, r), dtype=np.int64)
    M[list(labels), np.arange(r)] = 1
    rep = [labels.index(x) for x in range(b)]
    C = np.einsum('xi,yj,ijk->xyk', M, M, p)[:, :, rep]  # fused p^Z_XY at a representative of Z
    return C


def report(path, labs, out, t0, masks):
    init(path)
    r = P.shape[0]
    rows = []
    for lab in sorted(labs, key=lambda l: (max(l), l)):
        rank = max(lab) + 1
        C = fused_constants(P, list(lab))
        comm = bool(np.array_equal(C, C.transpose(1, 0, 2)))
        blocks = [[k for k in range(r) if lab[k] == x] for x in range(rank)]
        symm = all(lab[PAIR[k]] == lab[k] for k in range(r))
        val = [int(P[blocks[x], :, 0].sum()) for x in range(rank)]
        rows.append({'rank': rank, 'commutative': comm, 'symmetric': symm, 'blocks': blocks, 'valencies': val})
    def coarser(a, b):
        return all(any(set(bb) <= set(aa) for aa in a['blocks']) for bb in b['blocks'])
    for i, a in enumerate(rows):
        a['id'] = i
    for a in rows:
        below = [b['id'] for b in rows if b is not a and coarser(a, b)]
        a['refined_by'] = [x for x in below
                           if not any(y != x and coarser(rows[y], rows[x]) for y in below)]
    info = {'input': path, 'rank': r, 'units': len(UNITS), 'masks': masks, 'fusions': rows,
            'seconds': round(time.time() - t0, 1)}
    json.dump(info, open(out, 'w'), indent=1)
    ncomm = sum(x['commutative'] for x in rows)
    print(f"rank={r} units={len(UNITS)} distinct singly generated fusions={len(rows)} commutative={ncomm} "
          f"ranks={sorted(x['rank'] for x in rows)} t={info['seconds']}s")


def main(path, out, shard=0, nshard=1):
    """Masks with the top unit absent suffice (S and its complement have the same closure). With nshard > 1,
    only masks = shard mod nshard are done and the raw label tuples go to out; merge with 'merge'."""
    t0 = time.time()
    init(path)
    half = 1 << (len(UNITS) - 1)
    labs = set()
    for mask in range(1 + shard, half, nshard):
        labs.add(closure_of(mask))
    if nshard == 1:
        report(path, labs, out, t0, half - 1)
    else:
        json.dump([list(l) for l in labs], open(out, 'w'))
        print(f'shard {shard}/{nshard}: {len(labs)} fusions, {time.time() - t0:.0f}s')


if __name__ == '__main__':
    if sys.argv[1] == 'merge':
        # python fusion_closure.py merge <csv> <out.json> <part1.json> ...
        t0 = time.time()
        labs = set()
        for f in sys.argv[4:]:
            labs |= {tuple(l) for l in json.load(open(f))}
        init(sys.argv[2])
        report(sys.argv[2], labs, sys.argv[3], t0, (1 << (len(UNITS) - 1)) - 1)
    else:
        main(sys.argv[1], sys.argv[2], *(int(x) for x in sys.argv[3:5]))
